import * as React from "react";
import { trackEvent } from "../utils/analytics";

type ImageAsset = {
  src: string;
  alt?: string;
  desc?: string;
};

export type LiveProjectCardData = {
  title: string;
  href: string;
  role: string;
  stack: string;
  year?: string;
  highlights: string[];
  note?: string;
  images: {
    logo: ImageAsset;
    large: ImageAsset;
  };
};

type ProjectCardProps = {
  project: LiveProjectCardData;
  detailsLabel: string;
  visitLabel: string;
  closeLabel: string;
};

const ProjectCard: React.FC<ProjectCardProps> = ({
  project,
  detailsLabel,
  visitLabel,
  closeLabel,
}) => {
  const [isOpen, setIsOpen] = React.useState(false);
  const dialogId = React.useId();

  React.useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    };

    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.body.style.overflow = "";
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen]);

  return (
    <>
      <article className="flex h-full flex-col overflow-hidden rounded-2xl border border-neutral/20 bg-secondary shadow-sm">
        <div className="relative border-b border-neutral/20 bg-primary/40 p-6">
          <img
            src={project.images.logo.src}
            alt={project.images.logo.alt || `${project.title} logo`}
            className="h-12 w-auto mx-auto"
            loading="lazy"
          />
        </div>
        <div className="flex flex-1 flex-col p-6">
          <h3 className="text-lg font-semibold leading-snug text-accent">{project.title}</h3>
          <p className="mt-1 text-sm text-neutral">
            <span className="font-medium text-accent">{project.role}</span>
            {" · "}
            <span>{project.stack}</span>
            {project.year ? <span>{" · "}{project.year}</span> : null}
          </p>

          <ul className="mt-4 flex-1 space-y-2 text-sm text-accent">
            {project.highlights.map((highlight) => (
              <li key={highlight} className="flex gap-2">
                <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
                <span className="min-w-0">{highlight}</span>
              </li>
            ))}
          </ul>

          {project.note ? <p className="my-4 text-sm text-neutral">{project.note}</p> : null}

          <div className="mt-auto flex w-full gap-3">
            <button
              type="button"
              onClick={() => setIsOpen(true)}
              className="inline-flex w-full flex-1 items-center justify-center rounded-xl border border-neutral/25 bg-primary px-3 py-2 text-sm font-medium text-accent hover:bg-primary/70"
              aria-label={`${detailsLabel}: ${project.title}`}
            >
              {detailsLabel}
            </button>
            <a
              href={project.href}
              target="_blank"
              rel="noreferrer"
              onClick={() =>
                trackEvent("portfolio_click", {
                  source: "portfolio.live.visit",
                  project_name: project.title,
                  target_url: project.href,
                })}
              className="inline-flex w-full flex-1 items-center justify-center rounded-xl bg-accent px-3 py-2 text-sm font-semibold text-primary hover:opacity-90"
              aria-label={`${visitLabel}: ${project.title}`}
            >
              {visitLabel}
            </a>
          </div>
        </div>
      </article>

      {isOpen ? (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby={dialogId}
          className="fixed inset-0 z-50 flex items-center justify-center px-4 py-10"
        >
          <div
            className="absolute inset-0 bg-primary/90 backdrop-blur-sm"
            onClick={() => setIsOpen(false)}
          />
          <div className="relative z-10 w-full max-w-5xl overflow-hidden rounded-3xl border border-neutral/20 bg-secondary shadow-2xl">
            <div className="flex items-center justify-between border-b border-neutral/20 px-6 py-4">
              <div className="flex items-center gap-3">
                <img
                  src={project.images.logo.src}
                  alt={project.images.logo.alt || `${project.title} logo`}
                  className="h-9 w-auto"
                />
                <h3 id={dialogId} className="text-lg font-semibold text-accent">
                  {project.title}
                </h3>
              </div>
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                className="inline-flex items-center rounded-xl border border-neutral/25 bg-primary px-3 py-2 text-sm font-medium text-accent hover:bg-primary/70"
              >
                {closeLabel}
              </button>
            </div>

            <div className="grid gap-6 p-6 lg:grid-cols-2">
              <div className="overflow-hidden rounded-2xl border border-neutral/20">
                <img
                  src={project.images.large.src}
                  alt={project.images.large.alt || project.title}
                  className="h-full w-full object-cover"
                />
              </div>
              <div>
                <p className="text-sm text-neutral">
                  <span className="font-medium text-accent">{project.role}</span>
                  {" · "}
                  <span>{project.stack}</span>
                  {project.year ? <span>{" · "}{project.year}</span> : null}
                </p>

                <ul className="mt-5 space-y-2 text-sm text-accent">
                  {project.highlights.map((highlight) => (
                    <li key={highlight} className="flex gap-2">
                      <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
                      <span className="min-w-0">{highlight}</span>
                    </li>
                  ))}
                </ul>

                {project.note ? <p className="mt-5 text-sm text-neutral">{project.note}</p> : null}
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
};

export default ProjectCard;
