import { UserProfile } from "../interfaces";
const userData: UserProfile = data;
import Layout from "../components/layout";
import Palette from "../components/palette";
import { AuditRequestButton } from "../components/auditRequestModal";
import  data  from "../data/data.json";
import Card, { type ArchiveProjectCardData } from "../components/card";
import ProjectCard, { type LiveProjectCardData } from "../components/projectCard";
import archiveImages from "../images/portfolio_archive";
import heroBackground from "../images/resume-hero.png";

import * as React from "react";
import { graphql, Link, type HeadFC, type PageProps } from "gatsby";
import { useTranslation } from "react-i18next";
import { useI18next } from "gatsby-plugin-react-i18next";
import SEO from "../components/seo";
import { trackEvent } from "../utils/analytics";
import { mapLiveProjectsWithImages, type LivePortfolioProject, type PortfolioProject } from "../utils/livePortfolio";

